  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Špilberk', 'Mohutná pevnost nad Brnem, kdysi obávaná žalářní kasematy, dnes muzeum s výhledem na město. Symbol moravské metropole.', 49.1947, 16.5989, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0pilberk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0pilberk.jpg"}'::text[], 0),
    (v_route, 'Hrad Veveří', 'Rozlehlý gotický hrad na ostrohu nad Brněnskou přehradou, jeden z nejstarších a největších v zemi. Malebná dominanta nad vodou.', 49.2558, 16.4622, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Veve%C5%99%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Veve%C5%99%C3%AD.jpg"}'::text[], 1),
    (v_route, 'Vila Tugendhat', 'Funkcionalistická vila architekta Miese van der Rohe, skvost moderní architektury zapsaný na seznam UNESCO. Ikona meziválečného Brna.', 49.2075, 16.6156, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vila_Tugendhat.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vila_Tugendhat.jpg"}'::text[], 2),
    (v_route, 'Brněnská přehrada', 'Oblíbené rekreační jezero na okraji Brna s výletními loděmi a plážemi. Osvěžující zastávka u vody.', 49.2411, 16.51, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brn%C4%9Bnsk%C3%A1_p%C5%99ehrada.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brn%C4%9Bnsk%C3%A1_p%C5%99ehrada.jpg"}'::text[], 3),
    (v_route, 'Katedrála Petrov', 'Gotická katedrála na skále nad Brnem se dvěma věžemi, symbol města ze stokorunové bankovky. Působivá dominanta.', 49.1911, 16.6075, 'https://commons.wikimedia.org/wiki/Special:FilePath/Petrov_Brno.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Petrov_Brno.jpg"}'::text[], 4);
