  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Slavkov (Austerlitz)', 'Barokní zámek, kde byl po bitvě u Slavkova roku 1805 uzavřen mír. Elegantní sídlo s historií tří císařů.', 49.1533, 16.8764, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Slavkov.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Slavkov.jpg"}'::text[], 0),
    (v_route, 'Mohyla míru', 'Secesní památník na místě nejkrvavějších bojů bitvy u Slavkova s muzeem. Pietní vrchol slavkovského bojiště.', 49.1281, 16.7614, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mohyla_m%C3%ADru.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mohyla_m%C3%ADru.jpg"}'::text[], 1),
    (v_route, 'Zámek Bučovice', 'Renesanční zámek s arkádovým nádvořím italského typu, klenot mezi moravskými zámky. Skvost daleko od davů.', 49.1497, 17.0, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Bu%C4%8Dovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Bu%C4%8Dovice.jpg"}'::text[], 2),
    (v_route, 'Rozhledna Urbanov', 'Vyhlídka nad slavkovským bojištěm s pohledem na místa historické bitvy. Klidná zastávka nad vinicemi.', 49.13, 16.83, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slavkov_u_Brna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slavkov_u_Brna.jpg"}'::text[], 3),
    (v_route, 'Ždánický les', 'Rozlehlý listnatý les jižně od bojiště, ráj klidných silnic. Osvěžující zastávka v zeleni.', 49.05, 16.95, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDd%C3%A1nick%C3%BD_les.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDd%C3%A1nick%C3%BD_les.jpg"}'::text[], 4);
