  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Sloupsko-šošůvské jeskyně', 'Rozsáhlý jeskynní systém se sály, propastmi a podzemní říčkou na severu Moravského krasu. Podzemní zážitek bez davů.', 49.4111, 16.7392, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sloupsko-%C5%A1o%C5%A1%C5%AFvsk%C3%A9_jeskyn%C4%9B.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sloupsko-%C5%A1o%C5%A1%C5%AFvsk%C3%A9_jeskyn%C4%9B.jpg"}'::text[], 0),
    (v_route, 'Poutní kostel Křtiny', 'Skvostný barokní poutní chrám od Santiniho zvaný perla Moravy. Duchovní zastávka mezi lesy.', 49.2975, 16.7461, 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C5%99tiny.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C5%99tiny.jpg"}'::text[], 1),
    (v_route, 'Blansko – zámek', 'Zámek s muzeem Blanenska a litinou, výchozí bod do Moravského krasu. Klidná zastávka na řece Svitavě.', 49.3644, 16.6439, 'https://commons.wikimedia.org/wiki/Special:FilePath/Blansko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Blansko.jpg"}'::text[], 2),
    (v_route, 'Rudické propadání', 'Působivé místo, kde potok mizí v podzemí krasu, s větrnou jeskyní. Zajímavá zastávka pro přírodovědce.', 49.394, 16.735, 'https://commons.wikimedia.org/wiki/Special:FilePath/Moravsk%C3%BD_kras.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Moravsk%C3%BD_kras.jpg"}'::text[], 3),
    (v_route, 'Jeskyně Balcarka', 'Bohatě zdobená krápníková jeskyně u Ostrova u Macochy. Barevný podzemní skvost.', 49.373, 16.755, 'https://commons.wikimedia.org/wiki/Special:FilePath/Balcarka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Balcarka.jpg"}'::text[], 4);
