  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Pernštejn', 'Skvostně zachovalý gotický hrad zvaný mramorový, jeden z nejkrásnějších v Česku, kulisa mnoha filmů. Nezapomenutelná dominanta Svratecka.', 49.5508, 16.3167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Pern%C5%A1tejn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Pern%C5%A1tejn.jpg"}'::text[], 0),
    (v_route, 'Nedvědice', 'Městečko pod Pernštejnem v údolí Svratky, výchozí bod k hradu. Klidná zastávka mezi kopci.', 49.4553, 16.35, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nedv%C4%9Bdice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nedv%C4%9Bdice.jpg"}'::text[], 1),
    (v_route, 'Doubravník – kostel', 'Obec s pozoruhodným renesančním kostelem a hrobkou Mitrovských. Klidná zastávka v údolí.', 49.4258, 16.3517, 'https://commons.wikimedia.org/wiki/Special:FilePath/Doubravn%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Doubravn%C3%ADk.jpg"}'::text[], 2),
    (v_route, 'Vírská přehrada', 'Malebná kamenná přehrada s vysokou hrází v hlubokém údolí Svratky. Působivá zastávka u vody.', 49.56, 16.213, 'https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADrsk%C3%A1_p%C5%99ehrada.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%ADrsk%C3%A1_p%C5%99ehrada.jpg"}'::text[], 3),
    (v_route, 'Zubří – rozhledna', 'Vyhlídkové místo nad údolím Svratky s pohledem do kraje. Klidná zastávka nad lesy.', 49.48, 16.29, 'https://commons.wikimedia.org/wiki/Special:FilePath/Svratka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Svratka.jpg"}'::text[], 4);
