  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Boskovice', 'Malebná zřícenina gotického hradu na kopci nad městem s dochovanými hradbami. Dominanta Boskovicka.', 49.4906, 16.66, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Boskovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Boskovice.jpg"}'::text[], 0),
    (v_route, 'Zámek Boskovice', 'Elegantní empírový zámek s dochovanými interiéry v centru města. Klidná zastávka pod hradem.', 49.4881, 16.6603, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Boskovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Boskovice.jpg"}'::text[], 1),
    (v_route, 'Židovské město Boskovice', 'Jedna z nejzachovalejších židovských čtvrtí v Česku se synagogou a hřbitovem. Cesta do minulosti.', 49.4881, 16.655, 'https://commons.wikimedia.org/wiki/Special:FilePath/Boskovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Boskovice.jpg"}'::text[], 2),
    (v_route, 'Westernové městečko Boskovice', 'Zábavní westernové městečko s koňmi a představeními. Zábavná zastávka pro celou posádku.', 49.49, 16.67, 'https://commons.wikimedia.org/wiki/Special:FilePath/Boskovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Boskovice.jpg"}'::text[], 3),
    (v_route, 'Jevíčko', 'Historické městečko s věží a náměstím na pomezí Čech a Moravy. Klidná zastávka mimo hlavní tahy.', 49.6331, 16.7139, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jev%C3%AD%C4%8Dko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jev%C3%AD%C4%8Dko.jpg"}'::text[], 4);
