  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Zámek Milotice', 'Skvostný barokní zámek s francouzskou zahradou zvaný perla jihovýchodní Moravy, kulisa mnoha pohádek. Elegantní zastávka Slovácka.', 48.9464, 17.14, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Milotice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_Milotice.jpg"}'::text[], 0),
    (v_route, 'Skanzen Strážnice', 'Národopisné muzeum v přírodě s ukázkou lidové architektury Slovácka a folklorními slavnostmi. Živá tradice regionu.', 48.9014, 17.3164, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skanzen_Str%C3%A1%C5%BEnice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skanzen_Str%C3%A1%C5%BEnice.jpg"}'::text[], 1),
    (v_route, 'Vinné sklepy Petrov-Plže', 'Malebná ulička bíle malovaných vinných sklepů, památková rezervace lidového stavitelství. Zastávka na slovácké víno.', 48.87, 17.253, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C5%BEe_Petrov.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pl%C5%BEe_Petrov.jpg"}'::text[], 2),
    (v_route, 'Zámek Strážnice', 'Renesanční zámek v parku, sídlo Ústavu lidové kultury. Klidná zastávka u Baťova kanálu.', 48.9014, 17.3164, 'https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%A1%C5%BEnice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%A1%C5%BEnice.jpg"}'::text[], 3),
    (v_route, 'Baťův kanál', 'Historický plavební kanál protkávající Slovácko, dnes ráj rekreační plavby. Zastávka u vody.', 48.9014, 17.3164, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C5%A5%C5%AFv_kan%C3%A1l.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C5%A5%C5%AFv_kan%C3%A1l.jpg"}'::text[], 4);
