  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bazilika Velehrad', 'Velkolepá poutní bazilika, nejvýznamnější cyrilometodějské poutní místo Moravy. Duchovní srdce národa.', 49.1064, 17.3939, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bazilika_Velehrad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bazilika_Velehrad.jpg"}'::text[], 0),
    (v_route, 'Archeoskanzen Modrá', 'Rekonstrukce velkomoravského opevněného sídliště nedaleko Velehradu. Cesta do dob Velké Moravy.', 49.1064, 17.36, 'https://commons.wikimedia.org/wiki/Special:FilePath/Modr%C3%A1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Modr%C3%A1.jpg"}'::text[], 1),
    (v_route, 'Živá voda Modrá', 'Expozice s prosklenou nádrží, kde lze pozorovat ryby pod hladinou. Zábavná zastávka pro rodiny.', 49.1064, 17.36, 'https://commons.wikimedia.org/wiki/Special:FilePath/Modr%C3%A1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Modr%C3%A1.jpg"}'::text[], 2),
    (v_route, 'Chřiby – Kazatelna', 'Skalní vyhlídka v lesnatých Chřibech s výhledem na Slovácko. Klidná zastávka mezi stromy.', 49.14, 17.38, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C5%99iby.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C5%99iby.jpg"}'::text[], 3),
    (v_route, 'Uherské Hradiště', 'Historické město na řece Moravě, srdce Slovácka s pěkným náměstím. Živá zastávka s dobrým zázemím.', 49.0697, 17.46, 'https://commons.wikimedia.org/wiki/Special:FilePath/Uhersk%C3%A9_Hradi%C5%A1t%C4%9B.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Uhersk%C3%A9_Hradi%C5%A1t%C4%9B.jpg"}'::text[], 4);
