  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Slovanské hradiště Mikulčice', 'Archeologický park na místě jednoho z hlavních center Velké Moravy s kostely a nálezy. Kolébka moravské státnosti.', 48.8064, 17.05, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mikul%C4%8Dice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mikul%C4%8Dice.jpg"}'::text[], 0),
    (v_route, 'Soutok Moravy a Dyje', 'Rozlehlé lužní lesy u trojmezí s Rakouskem a Slovenskem, ráj ptactva a starých dubů. Divoká zastávka na jihu.', 48.68, 16.94, 'https://commons.wikimedia.org/wiki/Special:FilePath/Soutok_Moravy_a_Dyje.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Soutok_Moravy_a_Dyje.jpg"}'::text[], 1),
    (v_route, 'Lanžhot', 'Nejjižnější město Moravy s folklorními tradicemi u hranice. Klidná zastávka mezi luhy.', 48.72, 16.97, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lan%C5%BEhot.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lan%C5%BEhot.jpg"}'::text[], 2),
    (v_route, 'Kostice – vinné sklepy', 'Vinařská obec Podluží s lidovými tradicemi a sklepy. Zastávka na jižní víno.', 48.745, 16.955, 'https://commons.wikimedia.org/wiki/Special:FilePath/Podlu%C5%BE%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Podlu%C5%BE%C3%AD.jpg"}'::text[], 3),
    (v_route, 'Pohansko', 'Archeologické naleziště velkomoravského dvorce s loveckým zámečkem u Břeclavi. Cesta do dávné minulosti.', 48.723, 16.885, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pohansko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pohansko.jpg"}'::text[], 4);
