  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Loucký klášter', 'Mohutný barokní klášter premonstrátů na okraji Znojma s vinařstvím. Působivá zastávka nad Dyjí.', 48.8394, 16.0334, 'https://commons.wikimedia.org/wiki/Special:FilePath/Louck%C3%BD_kl%C3%A1%C5%A1ter.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Louck%C3%BD_kl%C3%A1%C5%A1ter.jpg"}'::text[], 0),
    (v_route, 'Znojemský hrad a Vlkova věž', 'Hrad s rotundou a vyhlídkovou věží nad meandrem Dyje. Historická dominanta města.', 48.8567, 16.0472, 'https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo.jpg"}'::text[], 1),
    (v_route, 'Šatovské vinné sklepy', 'Malebná ulička vinných sklepů s malovaným sklepem v obci u hranice. Zastávka na znojemské víno.', 48.79, 16.06, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0atov.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0atov.jpg"}'::text[], 2),
    (v_route, 'Vyhlídka nad Dyjí (Králův stolec)', 'Skalní vyhlídka nad meandry Dyje v národním parku. Pohled na divokou řeku v soutěsce.', 48.85, 15.9, 'https://commons.wikimedia.org/wiki/Special:FilePath/Podyj%C3%AD.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Podyj%C3%AD.jpg"}'::text[], 3),
    (v_route, 'Konice – kaple', 'Vinařská obec u Znojma s poutní kaplí a sklepy. Klidná zastávka mezi vinicemi.', 48.83, 16.03, 'https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo.jpg"}'::text[], 4);
