  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Klášter Rajhrad', 'Nejstarší benediktinský klášter na Moravě s barokní bazilikou od Santiniho a Památníkem písemnictví. Duchovní a kulturní klenot.', 49.0906, 16.6122, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter_Rajhrad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%A1%C5%A1ter_Rajhrad.jpg"}'::text[], 0),
    (v_route, 'Zámek Židlochovice', 'Barokní lovecký zámek s rozlehlým parkem, kdysi oblíbené sídlo císaře. Elegantní zastávka nad Svratkou.', 49.042, 16.62, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_%C5%BDidlochovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek_%C5%BDidlochovice.jpg"}'::text[], 1),
    (v_route, 'Výhon u Židlochovic', 'Nejvyšší kopec jižně od Brna s vyhlídkou na Pálavu a vinice. Klidná zastávka nad krajem.', 49.03, 16.63, 'https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%BDhon.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/V%C3%BDhon.jpg"}'::text[], 2),
    (v_route, 'Nosislav – vinné sklepy', 'Vinařská obec s tradičními sklepy uprostřed vinic. Zastávka na jihomoravské víno.', 48.96, 16.64, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nosislav.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nosislav.jpg"}'::text[], 3),
    (v_route, 'Blučina', 'Obec s archeologickými nálezy a vinicemi nad Svratkou. Klidná zastávka mezi révou.', 49.058, 16.647, 'https://commons.wikimedia.org/wiki/Special:FilePath/Blu%C4%8Dina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Blu%C4%8Dina.jpg"}'::text[], 4);
